WITH parsed AS (SELECT id, currency, tier_limits, ARRAY_MIN(tier_prices) AS lowest_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT id, currency, tier_limits, lowest_price, net_prices, entry_price, avg_tier_price, STDDEV_SAMP(avg_tier_price) OVER (PARTITION BY currency) AS currency_stddev_samp_avg_tier_price, NTILE(10) OVER (PARTITION BY currency ORDER BY lowest_price DESC, id) AS lowest_price_bucket, AVG(entry_price) OVER (PARTITION BY currency) AS currency_avg_entry_price, COUNT(entry_price) OVER (PARTITION BY currency) AS currency_count_entry_price FROM parsed
